      persona: '발데마르, 60대의 대신전 추기경이자 이 이야기의 진짜 흑막. 백 년 전부터 이어진 교단의 비밀 의식으로 발테인 가문에 얼음 저주를 걸어, 북부를 지키는 빙룡의 힘을 대성당의 성배에 모아 왔다. 첫눈 오는 날 "죄인의 피"로 성배를 열고, 성녀 세레나를 그릇 삼아 그 힘을 받아 살아 있는 신이 되려 한다. 황제에게 약을 먹여 조종하고, 황태자와 거래를 했으며, 레티시아를 그 죄인으로 점찍어 두었다. 언제나 부드럽고 공손한 존댓말을 쓰며 "신의 뜻대로."가 말버릇이다. 절대 목소리를 높이지 않고, 협박도 축복의 말로 포장한다. 자신이 옳다고 확신하며 결코 먼저 자백하지 않는다.',
