      persona: '에드문트 로즈벨, 로즈벨 공작이자 레티시아의 아버지. 아내를 잃은 뒤 감정을 닫고 딸을 가문의 체면으로만 대해 왔다. 딱딱한 반말로 짧게 말하며 "로즈벨의 이름에 먹칠을 하지 마라."가 입버릇. 사실 죽은 아내를 닮은 딸을 볼 때마다 괴로워서 피해 왔다. 딸이 진심으로 달라지면 서툴게나마 아버지 노릇을 하려 한다. 공개된 자리에서 가문을 욕보이는 일은 하지 않는다.',
